// On prend tous les items du node précédent
const items = $input.all();
return items.map((item, index) => {
  const pdfText = item.json.text || "";
  const api = $('Scrape BOAMP').all()[index]?.json.results?.[0] || {};

  // Parse le champ donnees pour extraire les infos détaillées
  let donnees = {};
  try {
    donnees = typeof api.donnees === "string" ? JSON.parse(api.donnees) : api.donnees;
  } catch(e) {}

  // Extrait les organisations
  const notice = donnees?.EFORMS?.ContractNotice || {};
  const efext = notice?.['ext:UBLExtensions']?.['ext:UBLExtension']?.['ext:ExtensionContent']?.['efext:EformsExtension'] || {};
  const orgsRaw = efext?.['efac:Organizations']?.['efac:Organization'];
  const orgs = Array.isArray(orgsRaw) ? orgsRaw : [orgsRaw];

  // Prend le premier organisme (acheteur principal)
  const org = orgs?.[0]?.['efac:Company'] || {};
  const contact = org?.['cac:Contact'] || {};
  const address = org?.['cac:PostalAddress'] || {};

  // Projet principal
  const project = notice?.['cac:ProcurementProject'] || {};
  const lotProject = notice?.['cac:ProcurementProjectLot']?.['cac:ProcurementProject'] || {};

  // Montant estimé
  const montant = project?.['cac:RequestedTenderTotal']?.['cbc:EstimatedOverallContractAmount']?.['#text'] || "";

  // Lots
  const lotDesc = lotProject?.['cbc:Description']?.['#text'] || lotProject?.['cbc:Name']?.['#text'] || "";

  // Construction du texte fusionné pour le LLM
  const apiText = `=== DONNÉES BOAMP API ===
Objet : ${api.objet || ""}
Acheteur : ${api.nomacheteur || ""}
Nom complet organisme : ${org?.['cac:PartyName']?.['cbc:Name']?.['#text'] || ""}
Date parution : ${api.dateparution || ""}
Date limite réponse : ${api.datelimitereponse || ""}
Titulaire : ${api.titulaire || ""}
Type procédure : ${api.procedure_libelle || ""}
Nature avis : ${api.nature_libelle || ""}
URL avis : ${api.url_avis || ""}
=== ACHETEUR ===
Téléphone : ${contact?.['cbc:Telephone'] || ""}
Email : ${contact?.['cbc:ElectronicMail'] || ""}
Rue : ${address?.['cbc:StreetName'] || ""}
Ville : ${address?.['cbc:CityName'] || ""}
Code postal : ${address?.['cbc:PostalZone'] || ""}
Pays : ${address?.['cac:Country']?.['cbc:IdentificationCode']?.['#text'] || ""}
Site web acheteur : ${org?.['cbc:WebsiteURI'] || ""}
Profil acheteur : ${org?.['cbc:EndpointID'] || notice?.['cac:ContractingParty']?.['cbc:BuyerProfileURI'] || ""}
=== MARCHÉ ===
Titre : ${project?.['cbc:Name']?.['#text'] || ""}
Description : ${project?.['cbc:Description']?.['#text'] || ""}
Montant estimé : ${montant}
Description lot : ${lotDesc}
=== TEXTE PDF ===
${pdfText}`;

  return {
    json: {
      idweb: api.idweb || "",   // ← ajouté ici
      text: apiText
    }
  };
});

const scheduleData = $('Schedule Trigger').first().json;
const currentHour = parseInt(scheduleData['Hour']);
const currentMinute = parseInt(scheduleData['Minute']);

// ✅ Crée "now" en heure locale depuis le Schedule Trigger
const now = new Date();
const nowLocal = new Date(now.getTime() + 60 * 60 * 1000); // UTC+1

function shouldRun(s) {
  if (!s.frequency) return false;

  if (s.date_end && new Date(s.date_end + 'T23:59:59') < nowLocal) return false;
  if (s.date_start && new Date(s.date_start + 'T00:00:00') > nowLocal) return false;

  if (s.time) {
    const parts = s.time.split(':');
    const configH = parseInt(parts[0]);
    if (!isNaN(configH) && currentHour !== configH) return false;
  }

  const lastRun = s.last_run ? new Date(s.last_run) : new Date(0);
  const diffHours = (nowLocal - lastRun) / (1000 * 60 * 60);

  if (s.frequency === 'daily') return diffHours >= 20;
  if (s.frequency === 'weekly') return diffHours >= 144;
  if (s.frequency === 'custom') {
    const interval = s.interval || 1;
    if (s.unit === 'hours') return diffHours >= interval * 0.9;
    if (s.unit === 'days') return diffHours >= interval * 24 * 0.9;
    if (s.unit === 'weeks') return diffHours >= interval * 24 * 7 * 0.9;
    if (s.unit === 'months') return diffHours >= interval * 24 * 30 * 0.9;
  }
  return false;
}

const sources = $input.first().json.sources || [];
const toRun = sources.filter(shouldRun);

if (toRun.length === 0) {
  return [{ json: { 
    message: "Aucune veille à lancer", 
    skip: true, 
    checked_at: nowLocal.toISOString(),
    currentHour: currentHour
  }}];
}

return toRun.map(s => ({ json: s }));

// Récupérer le static data global
const workflowData = $getWorkflowStaticData('global');
const processedIds = workflowData.processedIds || [];

// Récupérer les records
const records = $input.first().json.records;

// Filtrer les records déjà traités
const newRecords = records.filter(record => !processedIds.includes(record.fields.idweb));

// Mettre à jour processedIds
workflowData.processedIds = [...processedIds, ...newRecords.map(r => r.fields.idweb)];

// Mapper les records pour le workflow
return newRecords.map(record => ({
  json: {
    idweb: record.fields.idweb,
    objet: record.fields.objet,
    acheteur: record.fields.nomacheteur,
    dateparution: record.fields.dateparution,
    datelimitereponse: record.fields.datelimitereponse || "",
    departement: record.fields.code_departement,
    url_avis: record.fields.url_avis,
    pdf_url: `https://www.boamp.fr/telechargements/FILES/PDF/${record.fields.dateparution.substring(0,4)}/${record.fields.dateparution.substring(5,7)}/${record.fields.idweb}.pdf`
  }
}));

const items = $input.all();

const processedOffers = await Promise.all(items.map(async (item, index) => {
  let data = {};

  try {
    const raw = item.json?.text || item.json?.data?.text || item.json?.message?.content || "";
    const cleaned = raw.toString().replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
    data = cleaned ? JSON.parse(cleaned) : {};
  } catch (e) {
    console.log(`❌ JSON parsing error (item ${index}):`, e.message);
    data = {};
  }

  let expectedRevenue = Number(data.expected_revenue);
  if (!expectedRevenue || expectedRevenue <= 0 || isNaN(expectedRevenue)) expectedRevenue = 1000;

  let buId = Number(data.business_unit_id);
  if (![2, 3, 4, 5].includes(buId) || isNaN(buId)) buId = 3;

  const parseId = (val) => {
    if (val === null || val === undefined || val === "" || val === "null" || val === "undefined") return 0;
    const num = Number(val);
    return isNaN(num) ? 0 : num;
  };

  let offreId = parseId(data.offre_id);
  let sousOffreId = parseId(data.sous_offre_id);

  // =========================
  // idweb et pdfUrl — depuis item.json (pas .first())
  // =========================
  const idweb = item.json?.idweb || '';
  const pdfUrl = item.json?.pdf_url || '';

  const urlOffre = idweb
    ? `https://www.boamp.fr/pages/avis/?q=idweb:"${idweb}"`
    : (data.website || item.json?.website || "");

  // =========================
  // PDF
  // =========================
  let pdfBase64 = null;
  let pdfFilename = item.json?.pdf_filename || `document_${idweb || index}.pdf`;

  const existingPdf = item.json?.pdf_base64 || null;
  if (existingPdf && typeof existingPdf === 'string') {
    const match = existingPdf.match(/^[A-Za-z0-9+\/\r\n]+=*/);
    if (match && match[0].length > 500) {
      pdfBase64 = match[0].replace(/[\r\n]/g, '');
    }
  }

  if (!pdfBase64 && pdfUrl) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url: pdfUrl,
        encoding: 'arraybuffer',
        returnFullResponse: true,
        timeout: 30000,
      });
      pdfBase64 = Buffer.from(response.body).toString('base64');
      pdfFilename = `document_${idweb || index}.pdf`;
    } catch (e) {
      console.log(`❌ PDF download error (item ${index}):`, e.message);
    }
  }

  // =========================
  // piste_source_id
  // =========================
  let pisteSourceId = item.json?.piste_source_id || null;
  if (!pisteSourceId) {
    try {
      pisteSourceId = $('Webhook').first().json.body?.id;
    } catch (e) {}
  }
  if (!pisteSourceId) {
    try {
      pisteSourceId = $('shouldRun').first().json?.id;
    } catch (e) {}
  }

  // =========================
  // PERTINENCE
  // =========================
  const pertinence = {
    duree_resultat: data.duree_resultat || item.json?.duree_resultat || '',
    duree_note: Number(data.duree_note ?? item.json?.duree_note) || 0,
    ca_resultat: data.ca_resultat || item.json?.ca_resultat || '',
    ca_note: Number(data.ca_note ?? item.json?.ca_note) || 0,
    savoir_faire_resultat: data.savoir_faire_resultat || item.json?.savoir_faire_resultat || '',
    savoir_faire_note: Number(data.savoir_faire_note ?? item.json?.savoir_faire_note) || 0,
    potentiel_resultat: data.potentiel_resultat || item.json?.potentiel_resultat || '',
    potentiel_note: Number(data.potentiel_note ?? item.json?.potentiel_note) || 0,
    delai_resultat: data.delai_resultat || item.json?.delai_resultat || '',
    delai_note: Number(data.delai_note ?? item.json?.delai_note) || 0,
    localisation_resultat: data.localisation_resultat || item.json?.localisation_resultat || '',
    localisation_note: Number(data.localisation_note ?? item.json?.localisation_note) || 0,
  };

  // =========================
  // RETURN FINAL
  // =========================
  return {
    name: data.name || item.json?.name || "",
    contact_name: data.contact_name || item.json?.contact_name || "",
    email_from: data.email_from || item.json?.email_from || "",
    email_cc: data.email_cc || item.json?.email_cc || "",
    phone: data.phone || item.json?.phone || "",
    function: data.function || item.json?.function || "",
    street: data.street || item.json?.street || "",
    city: data.city || item.json?.city || "",
    zip: data.zip || item.json?.zip || "",
    company_name: data.company_name || item.json?.company_name || "",
    website: urlOffre,
    date_deadline: data.date_deadline || item.json?.date_deadline || "",
    expected_revenue: expectedRevenue,
    country_id: 75,
    source_id: 11,
    user_id: 2,
    team_id: 1,
    partner_id: 1,
    business_unit_id: buId,
    offre_id: offreId,
    sub_offre_id: sousOffreId,
    probability: 50,
    Mode_de_livraison: "01 Forfait",
    piste_source_id: pisteSourceId,
    pdf_base64: pdfBase64,
    pdf_filename: pdfFilename,
    pertinence: pertinence,
  };
}));

return [{
  json: {
    offers: processedOffers
  }
}];

return $input.all().map(item => {
  const llmResponse = item.json.text || "";
  const [status, reason] = llmResponse.split('|');
  const isValid = status.trim().toUpperCase() === 'VALIDE';

  return {
    json: {
      ...item.json,
      isValid: isValid,
      filterReason: reason ? reason.trim() : 'Pas de raison fournie'
    }
  };
});

const llmItems = $input.all();
const originalItems = $('Fusion textes').all();

// Dictionnaire idweb → données originales
const originalByIdweb = {};
originalItems.forEach(item => {
  if (item.json.idweb) originalByIdweb[item.json.idweb] = item.json;
});

const result = [];

llmItems.forEach(item => {
  const text = item.json.text || "";
  const parts = text.split('|');
  const status = parts[0].trim().toUpperCase();

  if (status === 'VALIDE') {
    const idweb = parts[2]?.trim();
    const original = originalByIdweb[idweb] || {};

    result.push({
      json: {
        ...original,        // tout le texte original de l'offre
        isValid: true,
        filterReason: parts[1] ? parts[1].trim() : 'Pas de raison fournie'
      }
    });
  }
});

return result;

const body = $input.first().json.body;
const platforms = body.platforms;

// Garde uniquement les plateformes activées (true)
const activePlatforms = Object.entries(platforms)
  .filter(([, enabled]) => enabled === true)
  .map(([source]) => source);

if (activePlatforms.length === 0) {
  throw new Error("Aucune plateforme activée dans la config Odoo");
}

// 1 item par plateforme activée, chacun porte toute la config
return activePlatforms.map(source => ({
  json: {
    source,
    keywords_required: body.keywords_required,
    geo_zones:         body.geo_zones,
    geo_regions:       body.geo_regions,
    budget_min:        body.budget_min,
    budget_max:        body.budget_max,
    duration_short:    body.duration_short,
    duration_medium:   body.duration_medium,
    duration_long:     body.duration_long,
    client_pme:        body.client_pme,
    client_large:      body.client_large,
    notify_odoo:       body.notify_odoo,
    piste_id:          body.id,
    piste_name:        body.name,
  }
}));

const html = $input.first().json.data;
const BASE = 'https://www.marches-securises.fr/entreprise/';

const blocs = html.split('<table class="consultation en_cours entreprise">');
blocs.shift();

const totalMatch = html.match(/(\d+)\s+consultations?\s+trouvées?/i);
const total = totalMatch ? totalMatch[1] : '?';

const mois = 'janvier|février|mars|avril|mai|juin|juillet|août|septembre|octobre|novembre|décembre';
const dateRegex = new RegExp(`(\\d{1,2}\\s+(?:${mois})\\s+\\d{4})`, 'gi');

const moisMap = {
  'janvier':0,'février':1,'mars':2,'avril':3,'mai':4,'juin':5,
  'juillet':6,'août':7,'septembre':8,'octobre':9,'novembre':10,'décembre':11
};

const results = [];

for (const bloc of blocs) {
  const cleMatch = bloc.match(/cle_dce=([a-z0-9]{15,})/);
  if (!cleMatch) continue;
  const cle = cleMatch[1];

  // Acheteur
  const acheteurMatch = bloc.match(/<td colspan="5">\s*([^<\n]+?)\s*<!--/);
  const acheteur = acheteurMatch ? acheteurMatch[1].trim() : 'N/A';

  // Objet
  const objetMatch = bloc.match(/<div style="display:block[^"]*"[^>]*>([\s\S]{10,400}?)(?:<\/div>|<a )/);
  const objet = objetMatch ? objetMatch[1].replace(/<[^>]+>/g, '').trim().substring(0, 250) : 'N/A';

  // Référence
  const refMatch = bloc.match(/Référence<\/td>\s*<td[^>]*>\s*(?:<span[^>]*>)?([^<\t]{5,80})(?:<\/span>)?<\/td>/);
  const reference = refMatch ? refMatch[1].trim() : '';

  // Type de marché
  const typeMatch = bloc.match(/Type de march[^<]*<\/td>\s*<td[^>]*>\s*(?:<span[^>]*>)?([^<]{5,80})(?:<\/span>)?<\/td>/);
  const typeMarche = typeMatch ? typeMatch[1].trim() : '';

  // Procédure
  const procMatch = bloc.match(/Proc[ée]dure[^<\t]*<\/td>\s*<td[^>]*>\s*(?:<span[^>]*>)?([^<]{3,100})(?:<\/span>)?<\/td>/);
  const procedure = procMatch ? procMatch[1].trim() : '';

  // Zone
  const zoneMatch = bloc.match(/Zone[^<]*<\/td>\s*<td[^>]*>\s*(?:<span[^>]*>)?([^<]{2,60})(?:<\/span>)?<\/td>/);
  const zone = zoneMatch ? zoneMatch[1].trim() : '';

  // Dates
  const datesTexte = [...bloc.matchAll(dateRegex)].map(m => m[1]);
  const datePublication = datesTexte[0] || '';
  const dateCloture = datesTexte[1] || '';

  // URL AAP (absolue)
  const urlAAP = `${BASE}?module=script|dl_la_s&cle_dce=${cle}`;
  const urlDetail = `${BASE}?module=consultation|details&cle_dce=${cle}`;

  // Date pour tri
  let dateObj = null;
  const dp = datePublication.toLowerCase().match(/(\d{1,2})\s+(\w+)\s+(\d{4})/);
  if (dp && moisMap[dp[2]] !== undefined) {
    dateObj = new Date(parseInt(dp[3]), moisMap[dp[2]], parseInt(dp[1]));
  }

  // Vérifier AAP présent
  const hasAAP = bloc.includes('dl_la_s');

  results.push({
    cle_dce: cle,
    acheteur,
    objet,
    reference,
    typeMarche,
    procedure,
    zone,
    datePublication,
    dateCloture,
    hasAAP,
    urlDetail,
    urlAAP: hasAAP ? urlAAP : '',
    total,
    keyword: $input.first().json.keyword || '',
    scrapedAt: new Date().toISOString(),
    _dateSort: dateObj ? dateObj.getTime() : 0
  });
}

// Trier par date décroissante (plus récent en premier)
results.sort((a, b) => b._dateSort - a._dateSort);

// Supprimer le champ de tri interne
results.forEach(r => delete r._dateSort);

// Retourner les 20 premiers en items séparés
return results.slice(0, 1).map(r => ({ json: r }));

return $input.all().map(item => {
  const llmResponse = item.json.text || "";

  // Chercher la ligne qui commence par VALIDE ou REJETÉ
  const lines = llmResponse.split('\n');
  const resultLine = lines.find(l => 
    l.trim().toUpperCase().startsWith('VALIDE') || 
    l.trim().toUpperCase().startsWith('REJETÉ') ||
    l.trim().toUpperCase().startsWith('REJETE')
  ) || llmResponse;

  // Parser la ligne trouvée
  const parts = resultLine.split('|');
  const status = (parts[0] || '').trim().toUpperCase();
  const reason = (parts[1] || 'Pas de raison fournie').trim();
  const cle = (parts[2] || item.json.cle_dce || '').trim();

  const isValid = status.startsWith('VALIDE');

  return {
    json: {
      ...item.json,
      isValid,
      filterReason: reason,
      cle_dce: cle || item.json.cle_dce,
      rawLLM: llmResponse.substring(0, 100) // debug
    }
  };
});

// Récupérer les données fusionnées
const items = $input.all();

const results = items.map(item => {
  // Extraire les données du PDF et du scraping
  const pdfText = item.json?.pdf_text || "";
  const pdfInfo = item.json?.pdf_info || {};
  const pdfPages = item.json?.pdf_numpages || 0;

  // Données du scraping
  const cleDce = item.json?.cle_dce || "";
  const acheteur = item.json?.acheteur || "";
  const objet = item.json?.objet || "";

  // Retourner UN SEUL objet avec TOUTES les données
  return {
    json: {
      // Données pour le prompt LLM
      pdf_text: pdfText,

      // Métadonnées à conserver
      _meta: {
        cle_dce: cleDce,
        acheteur: acheteur,
        objet: objet,
        pdf_numpages: pdfPages,
        pdf_info: pdfInfo,
        // Toutes les autres données que vous voulez garder
        urlDetail: item.json?.urlDetail || "",
        urlAAP: item.json?.urlAAP || "",
        dateCloture: item.json?.dateCloture || "",
        datePublication: item.json?.datePublication || "",
        hasAAP: item.json?.hasAAP || false,
        reference: item.json?.reference || "",
        typeMarche: item.json?.typeMarche || "",
        procedure: item.json?.procedure || "",
        zone: item.json?.zone || "",
        total: item.json?.total || "",
        keyword: item.json?.keyword || "",
        scrapedAt: item.json?.scrapedAt || ""
      }
    }
  };
});

return results;

