const allItems = $input.all();

// Trouver le marché actuel — chercher dans tous les items
let marcheActuel = '';
for (const item of allItems) {
  const t = item.json?.text || '';
  if (t.includes('name') && t.includes('email_from')) {
    // Nettoyer les backticks markdown
    marcheActuel = t.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
    break;
  }
}

// Trouver les items du sheet (ont partner_id)
const wonItems = allItems.filter(i => i.json?.partner_id);

const wonTexte = wonItems.slice(0, 30).map(i => {
  const d = i.json;
  return `✅ ${d.name || ''} | ${d.partner_id || ''} | ${d.business_unit_id || ''} | ${d.offre_id || ''} | ${d.expected_revenue || ''}€`;
}).join('\n');

const texteComplet = `
=== HISTORIQUE MARCHÉS GAGNÉS STUDIA ===
${wonTexte || 'Aucun historique disponible'}

=== NOUVEAU MARCHÉ À ÉVALUER ===
${marcheActuel}
`;

return [{ json: { text: texteComplet } }];

// ============================================================
// FUSION DES 3 SOURCES DU MERGE EN 1 SEUL LEAD
// ============================================================

const mergedItems = $input.all();
console.log(`Items reçus du Merge: ${mergedItems.length}`);

if (mergedItems.length !== 3) {
  throw new Error(`Expected 3 items from merge, got ${mergedItems.length}`);
}

// ==========================================================
// 1️⃣ ITEM 0 : LLM PERTINENCE (notes d'analyse)
// ==========================================================
let pertinenceData = {};
try {
  const pertText = mergedItems[0].json?.text || "";
  const cleaned = pertText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  pertinenceData = JSON.parse(cleaned);
  console.log("✓ Pertinence parsée:", Object.keys(pertinenceData));
} catch (e) {
  console.log("❌ Erreur parsing pertinence:", e.message);
}

// ==========================================================
// 2️⃣ ITEM 1 : LLM MARKET (données du marché)
// ==========================================================
let marketData = {};
try {
  const marketText = mergedItems[1].json?.text || "";
  const cleaned = marketText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  marketData = JSON.parse(cleaned);
  console.log("✓ Market data parsé:", marketData.name || "no name");
} catch (e) {
  console.log("❌ Erreur parsing market:", e.message);
}

// ==========================================================
// 3️⃣ ITEM 2 : EXTRACT PDF (métadonnées du vrai PDF)
// ==========================================================
const pdfItem = mergedItems[2].json || {};
const pdfData = {
  numpages: pdfItem.numpages || 0,
  text: pdfItem.text || "",              // VRAI texte du PDF (34 pages)
  info: pdfItem.info || {},
  pdf_base64: pdfItem.pdf_base64 || null,
  pdf_url: pdfItem.pdf_url || null,
  idweb: pdfItem.idweb || ""
};
console.log(`✓ PDF détecté: ${pdfData.numpages} pages`);

// ==========================================================
// 4️⃣ VALIDATION ET NETTOYAGE DES DONNÉES
// ==========================================================

// Revenue (depuis marketData)
let expectedRevenue = Number(marketData.expected_revenue);
if (!expectedRevenue || expectedRevenue <= 0 || isNaN(expectedRevenue)) {
  expectedRevenue = 0;
}

// Business Unit
let buId = Number(marketData.business_unit_id);
if (!buId || isNaN(buId)) buId = null;

// Parse IDs optionnels
const parseId = (val) => {
  if (!val || val === "" || val === "null" || val === "undefined" || val === null) {
    return null;
  }
  const num = Number(val);
  return isNaN(num) ? null : num;
};

// URL BOAMP (construite depuis idweb ou website)
const idweb = pdfData.idweb || marketData.idweb || "";
const websiteUrl = (marketData.website || "").trim();
const urlOffre = idweb 
  ? `https://www.boamp.fr/pages/avis/?q=idweb:"${idweb}"`
  : websiteUrl;

// ==========================================================
// 5️⃣ GESTION DU PDF (Base64)
// ==========================================================
let pdfBase64 = pdfData.pdf_base64;
let pdfFilename = idweb 
  ? `BOAMP_${idweb}.pdf` 
  : `document_${new Date().toISOString().split('T')[0]}.pdf`;

// Si pas de base64 mais URL disponible, télécharger
if (!pdfBase64 && pdfData.pdf_url) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: pdfData.pdf_url,
      encoding: 'arraybuffer',
      returnFullResponse: true,
      timeout: 30000,
    });
    pdfBase64 = Buffer.from(response.body).toString('base64');
    console.log("✓ PDF téléchargé depuis URL");
  } catch (e) {
    console.log("❌ Erreur download PDF:", e.message);
  }
}

// Nettoyer le base64
if (pdfBase64 && typeof pdfBase64 === 'string') {
  pdfBase64 = pdfBase64.replace(/^data:.*?;base64,/, '').replace(/[\r\n]/g, '');
}

// ==========================================================
// 6️⃣ PISTE SOURCE ID
// ==========================================================
let pisteSourceId = null;
try {
  pisteSourceId = $('Webhook').first().json.body?.id;
} catch (e) {
  // Fallback: chercher dans les données du PDF ou market
  pisteSourceId = pdfItem.body?.id || marketData.piste_source_id || null;
}

// ==========================================================
// 7️⃣ CONSTRUCTION OBJET PERTINENCE (format API Odoo)
// ==========================================================
const pertinence = {
  duree_resultat: pertinenceData.duree_resultat || "",
  duree_note: Number(pertinenceData.duree_note) || 0,
  ca_resultat: pertinenceData.ca_resultat || "",
  ca_note: Number(pertinenceData.ca_note) || 0,
  savoir_faire_resultat: pertinenceData.savoir_faire_resultat || "",
  savoir_faire_note: Number(pertinenceData.savoir_faire_note) || 0,
  potentiel_resultat: pertinenceData.potentiel_resultat || "",
  potentiel_note: Number(pertinenceData.potentiel_note) || 0,
  delai_resultat: pertinenceData.delai_resultat || "",
  delai_note: Number(pertinenceData.delai_note) || 0,
  localisation_resultat: pertinenceData.localisation_resultat || "",
  localisation_note: Number(pertinenceData.localisation_note) || 0
};

// Calcul score global
const notes = [
  pertinence.duree_note,
  pertinence.ca_note,
  pertinence.savoir_faire_note,
  pertinence.potentiel_note,
  pertinence.delai_note,
  pertinence.localisation_note
];
const totalNotes = notes.reduce((a, b) => a + b, 0);
pertinence.score_global = Math.round((totalNotes / 6) * 10) / 10;

console.log(`Score global calculé: ${pertinence.score_global}/10`);

// ==========================================================
// 8️⃣ STRUCTURE FINALE UNIQUE POUR ODOO API
// ==========================================================
const offer = {
  // === INFORMATIONS PRINCIPALES ===
  name: marketData.name || "",
  contact_name: marketData.contact_name || "",
  email_from: marketData.email_from || "",
  email_cc: marketData.email_cc || "",
  phone: marketData.phone || "",
  function: marketData.function || "",

  // === ADRESSE ===
  street: marketData.street || "",
  city: marketData.city || "",
  zip: marketData.zip || "",
  country_id: 75,

  // === ENTREPRISE ===
  partner_name: marketData.company_name || "",
  website: urlOffre,

  // === INFORMATIONS MARCHÉ ===
  date_deadline: marketData.date_deadline || "",
  expected_revenue: expectedRevenue,
  probability: 50,
  Mode_de_livraison: "01 Forfait",

  // === ASSIGNATION ===
  user_id: 2,
  team_id: 1,
  partner_id: 1,
  source_id: 11,

  // === CLASSIFICATION ===
  business_unit_id: buId,
  offre_id: parseId(marketData.offre_id),
  sub_offre_id: parseId(marketData.sous_offre_id),
  piste_source_id: pisteSourceId,

  // === PDF ===
  pdf_base64: pdfBase64,
  pdf_filename: pdfFilename,

  // === PERTINENCE (objet complet pour Odoo) ===
  pertinence: pertinence,

  // === MÉTADONNÉES (debug, optionnel) ===
  _pdf_numpages: pdfData.numpages,
  _pdf_text_preview: pdfData.text ? pdfData.text.substring(0, 100) + "..." : "",
  _idweb: idweb
};

// ==========================================================
// RETOUR : 1 SEUL LEAD FUSIONNÉ
// ==========================================================
return [{
  json: {
    offers: [offer]  // Tableau avec 1 seul élément !
  }
}];
